<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\ConsentPurposeDescriptionVO;

trait ConsentPurposeDescriptionAccessor
{
    private ConsentPurposeDescriptionVO $_description;
    public function getDescription(): string
    {
        return $this->_description->value();
    }
    public function description(): ConsentPurposeDescriptionVO
    {
        return $this->_description;
    }
    public function isDescriptionChanged(?self $original = null): bool
    {
        return !$this->_description->equals($original?->_description);
    }
    public function withDescription(ConsentPurposeDescriptionVO|string $description): self
    {
        $copy = clone $this;
        $copy->_description = ConsentPurposeDescriptionVO::from($description);
        return $copy;
    }
}
